SELECT gen_random_uuid()::text, 'formula', '$A_{net} = k_sA_{gross}$', 'Stacking Factor', '$A_{net} = k_sA_{gross},\qquad B = \frac{\Phi}{k_sA_{gross}}$', '$\text{m}^2$', 'The iron area of a laminated core: the insulation between sheets carries no flux.', '[{"symbol":"$k_s$","meaning":"stacking factor, about 0.9 to 0.95 for laminations","unit":null},{"symbol":"$A_{gross}$","meaning":"core cross-section measured over the stack","unit":"$\\text{m}^2$"}]'::jsonb, 'Use the NET area for flux density in the iron, the gross area for the air gap.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'magnetic circuits' AND s."active"), NULL, false, 'PENDING', now(), now()
