SELECT gen_random_uuid()::text, 'formula', '$A_g \approx (a + g)(b + g)$', 'Fringing at an Air Gap', '$A_g \approx (a + g)(b + g),\qquad B_g = \frac{\Phi}{A_g}$', '$\text{m}^2$', 'Flux bulges out at a gap, so the gap''s effective area is larger than the pole face.', '[{"symbol":"$a, b$","meaning":"pole-face dimensions","unit":"$\\text{m}$"},{"symbol":"$g$","meaning":"gap length","unit":"$\\text{m}$"}]'::jsonb, 'Fringing LOWERS the gap flux density and the ampere-turns the gap needs.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'magnetic circuits' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE'
