SELECT gen_random_uuid()::text, 'formula', '$\mathcal{F} = \Phi_c\mathcal{R}_{eq}$', 'Magnetic Circuit with Parallel Paths', '$\mathcal{F} = \Phi_c\mathcal{R}_{eq},\quad \mathcal{R}_{eq} = \mathcal{R}_c + \frac{\mathcal{R}_1\mathcal{R}_2}{\mathcal{R}_1 + \mathcal{R}_2},\quad \Phi_1\mathcal{R}_1 = \Phi_2\mathcal{R}_2$', '$\text{At}$', 'A shell-type core: reluctances combine like resistors, and the outer legs split the centre flux.', '[{"symbol":"$\\mathcal{R}_c$","meaning":"reluctance of the leg carrying the coil","unit":"$\\text{At/Wb}$"},{"symbol":"$\\mathcal{R}_1, \\mathcal{R}_2$","meaning":"reluctances of the two outer paths","unit":"$\\text{At/Wb}$"},{"symbol":"$\\Phi_c$","meaning":"flux in the centre leg, Φ₁ + Φ₂","unit":"$\\text{Wb}$"}]'::jsonb, 'The two outer legs have the SAME mmf across them; the flux divides inversely as their reluctance.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'magnetic circuits' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
