SELECT gen_random_uuid()::text, 'formula', '$B_m = \frac{V}{4.44fNA}$', 'Peak Core Flux Density', '$B_m = \frac{V}{4.44fNA},\qquad \Phi_m = \frac{V}{4.44fN}$', '$\text{T}$', 'How hard the core is worked: the flux the applied voltage forces through it.', '[{"symbol":"$V$","meaning":"RMS winding voltage","unit":"$\\text{V}$"},{"symbol":"$f$","meaning":"frequency","unit":"$\\text{Hz}$"},{"symbol":"$N$","meaning":"turns","unit":null},{"symbol":"$A$","meaning":"net core area","unit":"$\\text{m}^2$"}]'::jsonb, 'Flux follows V/f: 60 Hz equipment on 50 Hz at the same voltage runs 20% more flux, and hotter.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'transformer principles and emf equation' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
