SELECT gen_random_uuid()::text, 'formula', '$I = \frac{S}{V}$', 'Transformer Rated Currents', '$I_1 = \frac{S}{V_1},\ I_2 = \frac{S}{V_2}\ (\text{single phase});\qquad I_L = \frac{S}{\sqrt3V_L}\ (\text{three phase})$', '$\text{A}$', 'The full-load current of each winding from the nameplate.', '[{"symbol":"$S$","meaning":"rated apparent power","unit":"$\\text{VA}$"},{"symbol":"$V$","meaning":"rated voltage of that winding","unit":"$\\text{V}$"}]'::jsonb, 'The low-voltage winding carries the larger current: a 10 kVA, 2400/240 V unit carries 4.17 A and 41.7 A.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'transformer principles and emf equation' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE'
