SELECT gen_random_uuid()::text, 'formula', '$I_0 = \sqrt{I_c^2 + I_m^2}$', 'Exciting Current Components', '$I_c = I_0\cos\theta_0,\quad I_m = I_0\sin\theta_0,\quad P_0 = V_1I_0\cos\theta_0$', '$\text{A}$', 'The no-load current splits into a part that supplies core loss and a part that magnetizes the core.', '[{"symbol":"$I_0$","meaning":"no-load (exciting) current","unit":"$\\text{A}$"},{"symbol":"$I_c$","meaning":"core-loss component, in phase with V","unit":"$\\text{A}$"},{"symbol":"$I_m$","meaning":"magnetizing component, lagging 90°","unit":"$\\text{A}$"}]'::jsonb, 'The magnetizing part is much the larger: no-load power factor is low, about 0.1 to 0.3.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'transformer principles and emf equation' AND s."active"), NULL, false, 'PENDING', now(), now()
