SELECT gen_random_uuid()::text, 'formula', '$Z_{eq1} = Z_1 + a^2Z_2$', 'Equivalent Impedance Referred to One Side', '$R_{eq1} = R_1 + a^2R_2,\quad X_{eq1} = X_1 + a^2X_2;\qquad Z_{eq2} = \frac{Z_{eq1}}{a^2}$', '$\Omega$', 'Both windings'' series impedances lumped on one side, for the approximate equivalent circuit.', '[{"symbol":"$R_1, X_1$","meaning":"primary winding resistance and reactance","unit":"$\\Omega$"},{"symbol":"$R_2, X_2$","meaning":"secondary winding resistance and reactance","unit":"$\\Omega$"},{"symbol":"$a$","meaning":"turns ratio N₁/N₂","unit":null}]'::jsonb, 'The magnetizing branch is moved to the terminals in the approximate circuit; it changes the answer very little.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'equivalent circuit' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE'
