SELECT gen_random_uuid()::text, 'formula', '$Z_{pu} = \frac{Z_{eq}S}{V^2}$', 'Per-Unit Impedance of a Transformer', '$Z_{pu} = \frac{Z_{eq}}{Z_{base}} = \frac{Z_{eq}S}{V^2} = \frac{I_{rated}Z_{eq}}{V}$', NULL, 'A transformer''s impedance as a fraction of its base: the same number from either side.', '[{"symbol":"$Z_{eq}$","meaning":"equivalent impedance referred to the side of V","unit":"$\\Omega$"},{"symbol":"$S$","meaning":"rating","unit":"$\\text{VA}$"},{"symbol":"$V$","meaning":"rated voltage of that side","unit":"$\\text{V}$"}]'::jsonb, 'Z_pu is also the voltage that circulates rated current in the short-circuit test, as a fraction of rated voltage.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'equivalent circuit' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE'
