SELECT gen_random_uuid()::text, 'formula', '$\mathbf{V}_{NL} = \mathbf{V} + \mathbf{I}Z_{eq}$', 'Regulation by Phasor Sum', '$\mathbf{V}_{NL} = \mathbf{V} + \mathbf{I}(R_{eq} + jX_{eq}),\qquad \text{VR} = \frac{|\mathbf{V}_{NL}| - V}{V}$', NULL, 'The exact regulation: the voltage needed at no load to give rated voltage at full load.', '[{"symbol":"$\\mathbf{V}$","meaning":"full-load terminal voltage (reference)","unit":"$\\text{V}$"},{"symbol":"$\\mathbf{I}$","meaning":"load current, at the load''s power-factor angle","unit":"$\\text{A}$"},{"symbol":"$R_{eq}, X_{eq}$","meaning":"equivalent impedance on that side","unit":"$\\Omega$"}]'::jsonb, 'Lagging current: I = I∠−θ. A leading load can make the regulation negative.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'regulation and efficiency' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE'
