SELECT gen_random_uuid()::text, 'formula', '$\text{VR} \approx r\cos\theta \pm x\sin\theta$', 'Approximate Regulation', '$\text{VR} \approx \frac{IR_{eq}\cos\theta \pm IX_{eq}\sin\theta}{V} = r\cos\theta \pm x\sin\theta\ (\text{pu})$', NULL, 'The quick regulation formula used in most board problems.', '[{"symbol":"$r, x$","meaning":"per-unit equivalent resistance and reactance","unit":null},{"symbol":"$\\theta$","meaning":"load power-factor angle","unit":null},{"symbol":"$\\pm$","meaning":"+ for lagging, − for leading","unit":null}]'::jsonb, 'Within a few tenths of a percent of the phasor answer for normal transformers.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'regulation and efficiency' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
