SELECT gen_random_uuid()::text, 'formula', '$P_{cu} = x^2P_{cu,FL}$', 'Copper Loss at Any Load', '$P_{cu} = x^2P_{cu,FL},\qquad x = \frac{S}{S_{rated}}$', '$\text{W}$', 'Copper loss grows with the square of the load; core loss stays the same.', '[{"symbol":"$x$","meaning":"fraction of full load","unit":null},{"symbol":"$P_{cu,FL}$","meaning":"full-load copper loss (short-circuit test at rated current)","unit":"$\\text{W}$"}]'::jsonb, 'At half load the copper loss is a QUARTER of full-load copper loss.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'regulation and efficiency' AND s."active"), NULL, false, 'PENDING', now(), now()
