SELECT gen_random_uuid()::text, 'formula', '$\eta_{AD} = \frac{W_{out}}{W_{in}}\ (24\text{ h})$', 'All-Day Efficiency', '$\eta_{AD} = \frac{W_{out}}{W_{out} + 24P_c + \sum x_k^2P_{cu,FL}t_k}\quad (\text{energies over 24 h})$', NULL, 'Efficiency on energy over a day, for distribution transformers that are lightly loaded most of the time.', '[{"symbol":"$W_{out}$","meaning":"energy delivered in the day","unit":"$\\text{kWh}$"},{"symbol":"$P_c$","meaning":"core loss, present all day","unit":"$\\text{kW}$"},{"symbol":"$x_k, t_k$","meaning":"load fraction and its hours","unit":null}]'::jsonb, 'Core loss counts for all 24 hours, even at no load; that is why distribution transformers have low core loss.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'regulation and efficiency' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE'
