SELECT gen_random_uuid()::text, 'formula', '$R_c = \frac{V^2}{P_{oc}},\ X_m = \frac{V}{I_m}$', 'Open-Circuit Test Parameters', '$I_c = \frac{P_{oc}}{V},\quad I_m = \sqrt{I_{oc}^2 - I_c^2},\quad R_c = \frac{V}{I_c} = \frac{V^2}{P_{oc}},\quad X_m = \frac{V}{I_m}$', '$\Omega$', 'The magnetizing branch from the no-load test.', '[{"symbol":"$V$","meaning":"rated voltage, applied to the low side","unit":"$\\text{V}$"},{"symbol":"$I_{oc}$","meaning":"no-load current","unit":"$\\text{A}$"},{"symbol":"$P_{oc}$","meaning":"wattmeter reading = core loss","unit":"$\\text{W}$"}]'::jsonb, 'The open-circuit test gives CORE loss; done at rated voltage on the low-voltage side for convenience.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'open and short circuit tests' AND s."active"), NULL, false, 'PENDING', now(), now()
