SELECT gen_random_uuid()::text, 'formula', '$R_{eq} = \frac{P_{sc}}{I_{sc}^2}$', 'Short-Circuit Test Parameters', '$Z_{eq} = \frac{V_{sc}}{I_{sc}},\quad R_{eq} = \frac{P_{sc}}{I_{sc}^2},\quad X_{eq} = \sqrt{Z_{eq}^2 - R_{eq}^2}$', '$\Omega$', 'The series impedance from the short-circuit test, referred to the side the meters are on.', '[{"symbol":"$V_{sc}$","meaning":"voltage that drives rated current, a few % of rated","unit":"$\\text{V}$"},{"symbol":"$I_{sc}$","meaning":"test current (rated)","unit":"$\\text{A}$"},{"symbol":"$P_{sc}$","meaning":"wattmeter reading = full-load copper loss","unit":"$\\text{W}$"}]'::jsonb, 'Done on the high-voltage side at reduced voltage; the core loss is negligible because the flux is so small.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'open and short circuit tests' AND s."active"), NULL, false, 'PENDING', now(), now()
