SELECT gen_random_uuid()::text, 'formula', '$S_{auto} = S_w\left(1 + \frac{V_c}{V_s}\right)$', 'Reconnected Two-Winding Transformer Rating', '$S_{auto} = S_w\left(1 + \frac{V_c}{V_s}\right)$', '$\text{VA}$', 'The rating of a two-winding transformer reconnected as an autotransformer, with each winding at its rated current.', '[{"symbol":"$S_w$","meaning":"two-winding rating","unit":"$\\text{VA}$"},{"symbol":"$V_s$","meaning":"voltage of the series winding","unit":"$\\text{V}$"},{"symbol":"$V_c$","meaning":"voltage of the common winding","unit":"$\\text{V}$"}]'::jsonb, 'A 10 kVA, 2400/240 V unit as a 2640/2400 V autotransformer handles 10 × (1 + 2400/240) = 110 kVA.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'autotransformers' AND s."active"), NULL, false, 'PENDING', now(), now()
