SELECT gen_random_uuid()::text, 'formula', '$\Delta\text{-Y}: V_{L2} = \frac{\sqrt3V_{L1}}{a}$', 'Three-Phase Transformer Line-Voltage Ratios', '$\text{Y-Y}, \Delta\text{-}\Delta: \frac{V_{L1}}{a};\quad \Delta\text{-Y}: \frac{\sqrt3V_{L1}}{a};\quad \text{Y-}\Delta: \frac{V_{L1}}{\sqrt3a}$', '$\text{V}$', 'Secondary line voltage for each connection of three single-phase units.', '[{"symbol":"$V_{L1}$","meaning":"primary line voltage","unit":"$\\text{V}$"},{"symbol":"$a$","meaning":"turns ratio of each single-phase unit (phase to phase)","unit":null}]'::jsonb, 'Δ-Y and Y-Δ also shift the phase by 30°: two banks in parallel must have the same shift.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'three-phase connections' AND s."active"), NULL, false, 'PENDING', now(), now()
