SELECT gen_random_uuid()::text, 'formula', '$S_{VV} = \sqrt3\,S_{unit}$', 'Open-Delta (V-V) Capacity', '$S_{VV} = \sqrt3\,S_{unit} = 0.577\,S_{\Delta\Delta} = 0.866\,(2S_{unit})$', '$\text{VA}$', 'Two units in open delta still supply three-phase load, at 57.7% of the three-unit capacity.', '[{"symbol":"$S_{unit}$","meaning":"rating of one single-phase unit","unit":"$\\text{VA}$"},{"symbol":"$S_{\\Delta\\Delta}$","meaning":"capacity of the closed delta, 3S_unit","unit":"$\\text{VA}$"}]'::jsonb, 'Each unit carries the full LINE current; only 86.6% of the two units'' combined rating is usable.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'three-phase connections' AND s."active"), NULL, false, 'PENDING', now(), now()
