SELECT gen_random_uuid()::text, 'formula', '$S_A = S_L\frac{Z_B}{Z_A + Z_B}$', 'Load Sharing of Parallel Transformers', '$S_A = S_L\frac{Z_B}{Z_A + Z_B},\qquad S_B = S_L\frac{Z_A}{Z_A + Z_B}\quad (\text{equal ratios; ohms on one side})$', '$\text{VA}$', 'Two transformers with equal ratios share load inversely as their impedances.', '[{"symbol":"$S_L$","meaning":"total load (complex)","unit":"$\\text{VA}$"},{"symbol":"$Z_A, Z_B$","meaning":"equivalent impedances referred to the same side","unit":"$\\Omega$"}]'::jsonb, 'Per unit on their own ratings: equal Z_pu means each takes load in proportion to its rating, which is what you want.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'parallel operation' AND s."active"), NULL, false, 'PENDING', now(), now()
