SELECT gen_random_uuid()::text, 'formula', '$I_c = \frac{E_A - E_B}{Z_A + Z_B}$', 'Circulating Current of Unequal Ratios', '$I_c = \frac{E_A - E_B}{Z_A + Z_B}$', '$\text{A}$', 'Paralleled transformers with different ratios drive a current round the loop even at no load.', '[{"symbol":"$E_A, E_B$","meaning":"open-circuit secondary voltages","unit":"$\\text{V}$"},{"symbol":"$Z_A, Z_B$","meaning":"equivalent impedances referred to the secondary","unit":"$\\Omega$"}]'::jsonb, 'Even a 1% voltage difference circulates a large current, because transformer impedances are only a few percent.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'parallel operation' AND s."active"), NULL, false, 'PENDING', now(), now()
