SELECT gen_random_uuid()::text, 'formula', '$\frac{E_2}{E_1} = \frac{N_2\Phi_2}{N_1\Phi_1}$', 'Generated EMF at a New Speed or Flux', '$\frac{E_2}{E_1} = \frac{N_2\Phi_2}{N_1\Phi_1}$', NULL, 'A DC machine''s EMF is proportional to speed times flux.', '[{"symbol":"$E$","meaning":"generated EMF","unit":"$\\text{V}$"},{"symbol":"$N$","meaning":"speed","unit":"$\\text{rpm}$"},{"symbol":"$\\Phi$","meaning":"flux per pole","unit":"$\\text{Wb}$"}]'::jsonb, 'At constant field current (unsaturated), EMF simply scales with speed.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'dc generator principles' AND s."active"), NULL, true, 'PENDING', now(), now()
