SELECT gen_random_uuid()::text, 'formula', '$I_a = I_L + I_f$', 'DC Generator Currents', '$\text{shunt: } I_a = I_L + I_f,\ I_f = \frac{V_t}{R_f};\qquad \text{series: } I_a = I_L = I_s$', '$\text{A}$', 'Where the armature current goes in shunt and series generators.', '[{"symbol":"$I_L$","meaning":"load current","unit":"$\\text{A}$"},{"symbol":"$I_f$","meaning":"shunt field current","unit":"$\\text{A}$"},{"symbol":"$R_f$","meaning":"shunt field circuit resistance","unit":"$\\Omega$"}]'::jsonb, 'In a long-shunt compound, the series field carries I_a; in a short-shunt, it carries I_L.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'dc generator principles' AND s."active"), NULL, false, 'PENDING', now(), now()
