SELECT gen_random_uuid()::text, 'formula', '$R_{f,crit} = \frac{dE}{dI_f}\Big|_{0}$', 'Critical Field Resistance', '$R_{f,crit} = \text{slope of the air-gap line of the OCC} = \frac{E}{I_f}\ (\text{linear part})$', '$\Omega$', 'A self-excited shunt generator builds up only if its field resistance is below the slope of its magnetization curve.', '[{"symbol":"$E$","meaning":"open-circuit EMF","unit":"$\\text{V}$"},{"symbol":"$I_f$","meaning":"field current","unit":"$\\text{A}$"}]'::jsonb, 'Failure to build up: field resistance too high, no residual flux, field connected backward, or speed too low.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'dc generator characteristics' AND s."active"), NULL, false, 'PENDING', now(), now()
