SELECT gen_random_uuid()::text, 'formula', '$\text{VR} = \frac{V_{NL} - V_{FL}}{V_{FL}}$', 'DC Generator Voltage Regulation', '$\text{VR} = \frac{V_{NL} - V_{FL}}{V_{FL}} \times 100\%$', NULL, 'How much a generator''s voltage falls from no load to full load.', '[{"symbol":"$V_{NL}, V_{FL}$","meaning":"terminal voltage at no load and full load, same speed and field setting","unit":"$\\text{V}$"}]'::jsonb, 'Shunt generators droop the most; over-compounded generators can have NEGATIVE regulation.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'dc generator characteristics' AND s."active"), NULL, true, 'PENDING', now(), now()
