SELECT gen_random_uuid()::text, 'formula', '$AT_d = \frac{ZI\beta}{360}$', 'Armature Reaction Ampere-Turns', '$AT_d = \frac{ZI\beta}{360},\qquad AT_c = ZI\left(\frac{1}{2P} - \frac{\beta}{360}\right)\quad (\text{per pole})$', '$\text{At}$', 'The demagnetizing and cross-magnetizing ampere-turns per pole when the brushes are shifted.', '[{"symbol":"$Z$","meaning":"total armature conductors","unit":null},{"symbol":"$I$","meaning":"current per conductor, I_a/a","unit":"$\\text{A}$"},{"symbol":"$\\beta$","meaning":"brush shift, mechanical degrees","unit":null},{"symbol":"$P$","meaning":"poles","unit":null}]'::jsonb, 'With no brush shift there is only cross-magnetization. Use MECHANICAL degrees: electrical ÷ (P/2).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'armature reaction and commutation' AND s."active"), NULL, false, 'PENDING', now(), now()
