SELECT gen_random_uuid()::text, 'formula', '$E_r = L\frac{2I}{T_c}$', 'Reactance Voltage in Commutation', '$E_r = L\frac{2I}{T_c}\ (\text{linear commutation}),\qquad T_c = \frac{w_b}{v_c}$', '$\text{V}$', 'The self-induced voltage that opposes current reversal in a coil under the brush, causing sparking.', '[{"symbol":"$L$","meaning":"inductance of the coil being commutated","unit":"$\\text{H}$"},{"symbol":"$I$","meaning":"conductor current, reversing to −I","unit":"$\\text{A}$"},{"symbol":"$T_c$","meaning":"commutation time","unit":"$\\text{s}$"},{"symbol":"$w_b, v_c$","meaning":"brush width and commutator surface speed","unit":null}]'::jsonb, 'Interpoles cancel it, carrying armature current so their help grows with load.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'armature reaction and commutation' AND s."active"), NULL, false, 'PENDING', now(), now()
