SELECT gen_random_uuid()::text, 'formula', '$T = \frac{PZ}{2\pi a}\Phi I_a$', 'DC Motor Torque', '$T = \frac{PZ}{2\pi a}\Phi I_a = K\Phi I_a = \frac{E_bI_a}{\omega}$', '$\text{N·m}$', 'The electromagnetic torque of a DC motor, proportional to flux times armature current.', '[{"symbol":"$P$","meaning":"poles","unit":null},{"symbol":"$Z$","meaning":"armature conductors","unit":null},{"symbol":"$a$","meaning":"parallel paths","unit":null},{"symbol":"$\\Phi$","meaning":"flux per pole","unit":"$\\text{Wb}$"},{"symbol":"$I_a$","meaning":"armature current","unit":"$\\text{A}$"}]'::jsonb, 'The same K appears in E = KΦω: one constant links voltage to speed and current to torque.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'dc motor torque and speed' AND s."active"), NULL, false, 'PENDING', now(), now()
