SELECT gen_random_uuid()::text, 'formula', '$T \propto I_a^2$', 'Series Motor Torque and Speed', '$T \propto \Phi I_a \propto I_a^2\ (\text{unsaturated}),\qquad N \propto \frac{V - I_a(R_a + R_s)}{I_a}$', NULL, 'In a series motor the field current is the armature current: huge starting torque, speed falling with load.', '[{"symbol":"$I_a$","meaning":"armature current","unit":"$\\text{A}$"},{"symbol":"$R_s$","meaning":"series field resistance","unit":"$\\Omega$"}]'::jsonb, 'Never run a series motor without load: its speed rises dangerously as current and flux fall.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'dc motor torque and speed' AND s."active"), NULL, true, 'PENDING', now(), now()
