SELECT gen_random_uuid()::text, 'formula', '$R_{st} = \frac{V}{I_{st}} - R_a$', 'Starting Resistance', '$R_{st} = \frac{V}{I_{st}} - R_a,\qquad I_{st} = kI_{rated}\ (k \approx 1.5\text{ to }2)$', '$\Omega$', 'The resistance to put in series with the armature so the starting current stays safe.', '[{"symbol":"$V$","meaning":"supply voltage","unit":"$\\text{V}$"},{"symbol":"$I_{st}$","meaning":"allowed starting current","unit":"$\\text{A}$"},{"symbol":"$R_a$","meaning":"armature resistance","unit":"$\\Omega$"}]'::jsonb, 'At standstill E_b = 0, so without it I = V/R_a, often 10 to 20 times rated current.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'dc motor starting and control' AND s."active"), NULL, false, 'PENDING', now(), now()
