INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$R_{k+1} = R_k\frac{I_2}{I_1}$', 'Starter Resistance Steps', '$R_{k+1} = R_k\frac{I_2}{I_1},\qquad R_a = R_1\left(\frac{I_2}{I_1}\right)^n,\qquad R_1 = \frac{V}{I_1}$', '$\Omega$', 'Grading a starter: each step cuts resistance when the current has fallen from I₁ to I₂.', '[{"symbol":"$I_1, I_2$","meaning":"upper and lower current limits","unit":"$\\text{A}$"},{"symbol":"$R_k$","meaning":"total armature-circuit resistance on step k","unit":"$\\Omega$"},{"symbol":"$n$","meaning":"number of starter sections cut out","unit":null}]'::jsonb, 'The resistances form a geometric series; n = ln(R₁/R_a) / ln(I₁/I₂), rounded up.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'dc motor starting and control' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$I_a^2R_a = P_{const}$', 'Maximum Efficiency of a DC Machine', '$I_a^2R_a = P_{const} \implies I_a = \sqrt{\frac{P_{const}}{R_a}}$', '$\text{A}$', 'A machine is most efficient at the load where its variable (copper) loss equals its constant loss.', '[{"symbol":"$R_a$","meaning":"armature resistance","unit":"$\\Omega$"},{"symbol":"$P_{const}$","meaning":"constant losses: core, friction, windage, shunt field","unit":"$\\text{W}$"}]'::jsonb, 'The same rule as the transformer: copper loss = core loss.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'losses and efficiency' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$P_{const} = VI_0 - I_{a0}^2R_a$', 'Swinburne''s Test', '$P_{const} = VI_0 - I_{a0}^2R_a;\qquad \eta = \frac{P_{in} - P_{const} - I_a^2R_a}{P_{in}}\ (\text{motor})$', '$\text{W}$', 'The constant losses of a shunt machine from a no-load run, then its efficiency at any load.', '[{"symbol":"$V, I_0$","meaning":"no-load supply voltage and current, running as a motor","unit":"$\\text{V}$"},{"symbol":"$I_{a0}$","meaning":"no-load armature current, I₀ − I_f","unit":"$\\text{A}$"},{"symbol":"$R_a$","meaning":"armature resistance","unit":"$\\Omega$"}]'::jsonb, 'Cheap and quick, but it ignores how armature reaction changes the core loss under load.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE' AND s."normKey" = 'losses and efficiency' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
